namespace Iryo.Billing;

public class Validator
{
	public bool Validate(string insuranceCard)
	{
		if (!string.IsNullOrWhiteSpace(insuranceCard))
		{
			return insuranceCard.StartsWith("H");
		}
		return false;
	}
}

